// AeroFleet fleet aggregator
// Accepts: aerofleet/<droneId>/<messageType>

// Dashboard command: clear current incidents and remember their IDs.
// Remembering cleared IDs prevents retained/replayed MQTT messages from restoring them.
if (msg.topic === "aerofleet/control/clear-incidents") {
    const fleet = flow.get("aerofleet_dashboard_fleet") || {};
    const currentIncidents = flow.get("aerofleet_dashboard_incidents") || [];
    const clearedIds = new Set(flow.get("aerofleet_dashboard_cleared_incident_ids") || []);

    // Mark every currently known incident as cleared, including per-drone cached incidents.
    currentIncidents.forEach(incident => {
        if (incident && incident.event_id) clearedIds.add(String(incident.event_id));
    });

    Object.values(fleet).forEach(drone => {
        if (drone && drone.incident && drone.incident.event_id) {
            clearedIds.add(String(drone.incident.event_id));
        }
        if (drone && typeof drone === "object") drone.incident = null;
    });

    // Keep a bounded tombstone list so old retained MQTT events cannot reappear.
    const clearedIdList = Array.from(clearedIds).slice(-500);
    flow.set("aerofleet_dashboard_cleared_incident_ids", clearedIdList);
    flow.set("aerofleet_dashboard_incidents", []);
    flow.set("aerofleet_dashboard_incidents_initialized", true);
    flow.set("aerofleet_dashboard_fleet", fleet);

    const history = flow.get("aerofleet_dashboard_history") || [];
    const onlineCount = Object.values(fleet).filter(drone =>
        drone.status && drone.status.online === true
    ).length;

    msg.payload = {
        fleet: Object.values(fleet),
        onlineCount: onlineCount,
        incidentCount: 0,
        incidents: [],
        history: history,
        updatedAt: new Date().toISOString()
    };

    return msg;
}

// Also accepts the HiveMQ prefix: aerofleet-dsdrone-4f7c92/<droneId>/<messageType>

const parts = (msg.topic || "").split("/");
if (parts.length !== 3) return null;

const topicRoot = parts[0];
const droneId = parts[1];
const type = parts[2];

const acceptedRoots = ["aerofleet", "aerofleet-dsdrone-4f7c92"];
if (!acceptedRoots.includes(topicRoot)) return null;
if (!droneId || !["telemetry", "status", "incident", "preview"].includes(type)) return null;

// Convert JSON strings into objects. Preview can also arrive as a raw base64 string.
let payload = msg.payload;
if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (err) {
        if (type === "preview") payload = { image_base64: payload };
        else {
            node.warn("Invalid JSON on " + msg.topic);
            return null;
        }
    }
}
if (payload === null || payload === undefined || typeof payload !== "object") return null;

const receivedAt = new Date().toISOString();

const fleet = flow.get("aerofleet_dashboard_fleet") || {};
if (!fleet[droneId]) {
    fleet[droneId] = {
        id: droneId,
        telemetry: {},
        status: {},
        incident: null,
        preview: null
    };
}

const drone = fleet[droneId];
if (type === "status" && (payload.online !== true || payload.stm_connected === false || payload.streaming === false)) {
    delete drone.speedFix;
}
if (type === "telemetry") {
    const fix = payload.position;
    const time = Date.parse(fix && fix.fix_timestamp);
    const previous = drone.speedFix;
    if (fix && fix.source === "simulated" && Number.isFinite(time) &&
        Number.isFinite(fix.latitude) && Math.abs(fix.latitude) <= 90 &&
        Number.isFinite(fix.longitude) && Math.abs(fix.longitude) <= 180) {
        if (!previous || time > previous.time) {
            let speed = null;
            if (previous && time - previous.time <= 5000) {
                const rad = Math.PI / 180;
                const dLat = (fix.latitude - previous.latitude) * rad;
                const dLon = (fix.longitude - previous.longitude) * rad;
                const a = Math.sin(dLat / 2) ** 2 +
                    Math.cos(previous.latitude * rad) * Math.cos(fix.latitude * rad) * Math.sin(dLon / 2) ** 2;
                const distance = 2 * 6371000 * Math.asin(Math.min(1, Math.sqrt(a)));
                speed = distance / ((time - previous.time) / 1000);
            }
            drone.speedFix = { time, latitude: fix.latitude, longitude: fix.longitude, speed };
        }
    } else {
        delete drone.speedFix;
    }
}

if (type === "incident") {
    // Keep a separate event list: one drone can report multiple incidents over time.
    let incidents = flow.get("aerofleet_dashboard_incidents");

    // Migrate legacy per-drone incidents only before the user has explicitly cleared the list.
    const incidentsInitialized = flow.get("aerofleet_dashboard_incidents_initialized") === true;
    if (!Array.isArray(incidents)) {
        if (incidentsInitialized) {
            incidents = [];
        } else {
            incidents = Object.values(fleet)
                .filter(drone => drone.incident && typeof drone.incident === "object")
                .map(drone => ({
                    ...drone.incident,
                    droneId: drone.id,
                    timestamp: drone.incident.timestamp || drone.lastSeen || receivedAt,
                    receivedAt: drone.incident.receivedAt || drone.lastSeen || receivedAt
                }));
        }
    }

    const incidentTimestamp = payload.timestamp || receivedAt;
    const eventId = String(payload.event_id || (droneId + "-" + (payload.type || "incident") + "-" + incidentTimestamp));
    const clearedIds = flow.get("aerofleet_dashboard_cleared_incident_ids") || [];

    // Ignore old retained/replayed messages whose event IDs were cleared by the user.
    if (clearedIds.includes(eventId)) {
        const currentIncidents = flow.get("aerofleet_dashboard_incidents") || [];
        const currentHistory = flow.get("aerofleet_dashboard_history") || [];
        const currentFleet = flow.get("aerofleet_dashboard_fleet") || fleet;
        const currentOnlineCount = Object.values(currentFleet).filter(drone =>
            drone.status && drone.status.online === true
        ).length;

        msg.payload = {
            fleet: Object.values(currentFleet),
            onlineCount: currentOnlineCount,
            incidentCount: currentIncidents.filter(incident =>
                ["fire", "smoke"].includes(String(incident.type || "").toLowerCase())
            ).length,
            incidents: currentIncidents,
            history: currentHistory,
            updatedAt: receivedAt
        };
        return msg;
    }

    const normalizedIncident = {
        ...payload,
        event_id: eventId,
        droneId: droneId,
        timestamp: incidentTimestamp,
        receivedAt: receivedAt
    };

    // Update an existing event with the same ID; otherwise append a new event.
    const existingIndex = incidents.findIndex(item => item.event_id === eventId);
    if (existingIndex >= 0) incidents[existingIndex] = normalizedIncident;
    else incidents.push(normalizedIncident);

    const toTime = item => {
        const parsed = Date.parse((item && (item.timestamp || item.receivedAt)) || "");
        return Number.isFinite(parsed) ? parsed : 0;
    };

    incidents.sort((a, b) => toTime(b) - toTime(a));
    if (incidents.length > 200) incidents.length = 200;

    flow.set("aerofleet_dashboard_incidents", incidents);
    flow.set("aerofleet_dashboard_incidents_initialized", true);

    // Preserve the latest incident on the individual drone record for the fleet view.
    fleet[droneId].incident = normalizedIncident;
} else {
    fleet[droneId][type] = payload;
}

fleet[droneId].lastSeen = receivedAt;
flow.set("aerofleet_dashboard_fleet", fleet);

// Bounded History view. Camera image data is deliberately not stored.
const history = flow.get("aerofleet_dashboard_history") || [];
const historyTimestamp = payload.timestamp || receivedAt;
let summary = "";

if (type === "telemetry") {
    summary = "Telemetry update · " + (payload.tracker_state || payload.state || "state unknown");
} else if (type === "status") {
    summary = payload.online === true ? "Drone online" + (payload.stream_state ? " · " + payload.stream_state : "") : "Drone offline";
} else if (type === "incident") {
    summary = (payload.type || "Incident") + " detected";
} else if (type === "preview") {
    summary = "Camera preview received";
}

history.push({
    timestamp: historyTimestamp,
    receivedAt: receivedAt,
    droneId: droneId,
    type: type,
    summary: summary
});

const toHistoryTime = item => {
    const parsed = Date.parse((item && (item.timestamp || item.receivedAt)) || "");
    return Number.isFinite(parsed) ? parsed : 0;
};

history.sort((a, b) => toHistoryTime(b) - toHistoryTime(a));
if (history.length > 250) history.length = 250;
flow.set("aerofleet_dashboard_history", history);

const incidents = flow.get("aerofleet_dashboard_incidents") || [];

const onlineCount = Object.values(fleet).filter(drone =>
    drone.status && drone.status.online === true
).length;

const incidentCount = incidents.filter(incident =>
    ["fire", "smoke"].includes(String(incident.type || "").toLowerCase())
).length;

msg.payload = {
    fleet: Object.values(fleet),
    onlineCount: onlineCount,
    incidentCount: incidentCount,
    incidents: incidents,
    history: history,
    updatedAt: receivedAt
};

return msg;

if (msg.topic !== "aerofleet/control/clear-incidents") {
    return null;
}

const fleet = flow.get("aerofleet_dashboard_fleet") || {};
const incidents = flow.get("aerofleet_dashboard_incidents") || [];

const clearedIds = new Set(
    flow.get("aerofleet_dashboard_cleared_incident_ids") || []
);

// Remember all deleted incident IDs.
incidents.forEach(incident => {
    if (incident.event_id) {
        clearedIds.add(String(incident.event_id));
    }
});

// Clear the incident cache of every drone.
Object.values(fleet).forEach(drone => {
    if (drone.incident && drone.incident.event_id) {
        clearedIds.add(String(drone.incident.event_id));
    }

    drone.incident = null;
});

// Save cleared IDs and empty incident list.
flow.set(
    "aerofleet_dashboard_cleared_incident_ids",
    Array.from(clearedIds).slice(-500)
);

flow.set("aerofleet_dashboard_incidents", []);
flow.set("aerofleet_dashboard_incidents_initialized", true);
flow.set("aerofleet_dashboard_fleet", fleet);

const history = flow.get("aerofleet_dashboard_history") || [];

const onlineCount = Object.values(fleet).filter(
    drone => drone.status && drone.status.online === true
).length;

// Send the updated dashboard data directly to the UI.
msg.topic = "aerofleet/dashboard/cleared";

msg.payload = {
    fleet: Object.values(fleet),
    onlineCount: onlineCount,
    incidentCount: 0,
    incidents: [],
    history: history,
    updatedAt: new Date().toISOString()
};

return msg;

// AeroFleet live telemetry simulator
// Emits 3 moving drones every second, status every 5 seconds,
// and one new incident every 20 seconds.
// Connect this node's output to the existing "Aggregate fleet data" node.

const drones = [
    { id: "sim01", lat: 40.41680, lon: -3.70380, phase: 0.0, altitude: 120 },
    { id: "sim02", lat: 40.41810, lon: -3.70090, phase: 2.1, altitude: 86 },
    { id: "sim03", lat: 40.41490, lon: -3.70620, phase: 4.2, altitude: 104 }
];

let tick = context.get("simTick") || 0;
tick += 1;
context.set("simTick", tick);

const now = new Date();
const timestamp = now.toISOString();
const messages = [];

drones.forEach((drone, index) => {
    // Small, smooth movement around each drone's starting GPS coordinate.
    const angle = (tick * 0.12) + drone.phase;
    const latitude = drone.lat + (Math.sin(angle) * 0.00018);
    const longitude = drone.lon + (Math.cos(angle) * 0.00022);

    const speed = 2.4 + (Math.sin(angle * 0.7) * 1.1);
    const altitude = drone.altitude + (Math.sin(angle * 0.45) * 4);
    const battery = Math.max(15, 96 - Math.floor(tick / 18) - index * 3);

    messages.push({
        topic: "aerofleet/" + drone.id + "/telemetry",
        payload: {
            timestamp: timestamp,
            tracker_state: speed > 1.2 ? "FLYING" : "HOVERING",
            position: {
                latitude: Number(latitude.toFixed(6)),
                longitude: Number(longitude.toFixed(6)),
                altitude: Number(altitude.toFixed(1)),
                source: "simulated",
                fix_timestamp: timestamp
            },
            speed_m_s: Number(speed.toFixed(2)),
            satellites: 12 + ((tick + index) % 5),
            battery_percent: battery,
            accel_m_s2: {
                x: Number((Math.sin(angle) * 0.35).toFixed(2)),
                y: Number((Math.cos(angle) * 0.28).toFixed(2)),
                z: Number((9.81 + Math.sin(angle * 0.5) * 0.12).toFixed(2))
            },
            gyro_rad_s: {
                x: Number((Math.sin(angle * 0.8) * 0.04).toFixed(3)),
                y: Number((Math.cos(angle * 0.6) * 0.04).toFixed(3)),
                z: Number((Math.sin(angle * 0.4) * 0.06).toFixed(3))
            }
        }
    });

    // Refresh online status every five seconds.
    if (tick % 5 === 0) {
        messages.push({
            topic: "aerofleet/" + drone.id + "/status",
            payload: {
                online: true,
                timestamp: timestamp
            }
        });
    }
});

// Create a fresh incident every 20 seconds, rotating between the three drones.
// IDs are unique, so the incident list can demonstrate chronological updates.
if (tick % 20 === 0) {
    const incidentDrone = drones[Math.floor(tick / 20 - 1) % drones.length];
    messages.push({
        topic: "aerofleet/" + incidentDrone.id + "/incident",
        payload: {
            event_id: "sim-" + incidentDrone.id + "-event-" + tick,
            timestamp: timestamp,
            type: "fire",
            confidence: Number((0.82 + ((tick % 7) * 0.02)).toFixed(2)),
            position: {
                latitude: incidentDrone.lat,
                longitude: incidentDrone.lon
            }
        }
    });
}

// One Function output; return several MQTT-shaped messages on that output.
return [messages];

format:
.af-shell {
    display:flex;
    height:calc(100vh - 64px);
    min-height:0;
    max-height:calc(100vh - 64px);
    background:#08111e;
    color:#e8f0fb;
    font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
    border:1px solid #1d3048;
    border-radius:16px;
    overflow:hidden
}
.af-sidebar {
    width:190px;
    flex:0 0 190px;
    background:#0b1727;
    border-right:1px solid #1c3048;
    display:flex;
    flex-direction:column;
    padding:24px 14px 18px;
    box-sizing:border-box
}
.af-brand {
    display:flex;
    align-items:center;
    gap:12px;
    padding:0 8px 30px;
    border-bottom:1px solid #1d3048
}
.af-brand-icon {
    font-size:36px;
    color:#4ca9ff;
    line-height:1
}
.af-brand-name {
    font-size:22px;
    font-weight:800;
    letter-spacing:-.5px
}
.af-brand-sub {
    font-size:10px;
    color:#8194ad;
    margin-top:3px
}
.af-nav {
    display:grid;
    gap:8px;
    margin-top:28px
}
.af-nav-item {
    width:100%;
    border:0;
    background:transparent;
    text-align:left;
    cursor:pointer;
    font:inherit;
    position:relative;
    display:flex;
    align-items:center;
    gap:14px;
    padding:13px 14px;
    color:#a9bad0;
    border-radius:9px;
    font-size:14px
}
.af-nav-item span {
    font-size:20px;
    width:22px;
    text-align:center;
    color:#8eadd1
}
.af-nav-item.active {
    background:#17365b;
    color:#fff;
    box-shadow:inset 3px 0 #3a9dff
}
.af-nav-item.active span {
    color:#56adff
}
.af-connection {
    margin-top:auto;
    border-top:1px solid #1d3048;
    padding:18px 8px 0;
    display:flex;
    align-items:center;
    gap:8px;
    font-size:11px;
    color:#9aadc5
}
.af-connection i,.af-live-dot {
    width:8px;
    height:8px;
    border-radius:50%;
    background:#22d68a;
    box-shadow:0 0 10px #22d68a;
    display:inline-block
}
.af-connection b {
    margin-left:auto;
    color:#26d995;
    font-size:9px;
    letter-spacing:1px
}
.af-main {
    flex:1;
    min-width:0;
    min-height:0;
    height:100%;
    overflow:hidden;
    display:flex;
    flex-direction:column;
    padding:12px 16px 8px;
    background:radial-gradient(ellipse at 70% 0%,#13243a 0%,#091321 45%,#08111e 100%);
    box-sizing:border-box
}
.af-top {
    display:flex;
    justify-content:space-between;
    align-items:center;
    gap:18px;
    padding-bottom:20px;
    border-bottom:1px solid #1c3048
}
.af-eyebrow {
    font-size:9px;
    letter-spacing:2px;
    color:#61aef4;
    font-weight:700
}
.af-top h1 {
    font-size:27px;
    line-height:1.2;
    margin:5px 0 3px;
    color:#f4f8ff;
    font-weight:750
}
.af-top p {
    font-size:12px;
    color:#91a4bd;
    margin:0
}
.af-kpis {
    display:flex;
    gap:9px;
    align-items:stretch
}
.af-kpi,.af-clock {
    display:flex;
    align-items:center;
    gap:10px;
    padding:10px 13px;
    background:#101f32;
    border:1px solid #263b55;
    border-radius:10px;
    min-width:112px
}
.af-kpi-icon {
    font-size:22px
}
.green {
    color:#28d98c
}
.red {
    color:#ff6574
}
.blue {
    color:#64b5ff
}
.af-kpi strong {
    display:block;
    font-size:18px;
    line-height:1.1
}
.af-kpi small {
    display:block;
    font-size:9px;
    color:#9eafc5;
    margin-top:3px
}
.af-clock {
    display:block;
    min-width:110px
}
.af-clock small,.af-clock span {
    display:block;
    color:#8194ad;
    font-size:8px;
    letter-spacing:1px
}
.af-clock strong {
    display:block;
    font-size:12px;
    margin:5px 0 2px
}
.af-clock span {
    font-size:9px
}
.af-toolbar {
    display:flex;
    align-items:end;
    gap:20px;
    padding:15px 0 12px
}
.af-select-wrap {
    width:210px
}
.af-select-wrap label {
    display:block;
    color:#9aadc5;
    font-size:9px;
    letter-spacing:1.4px;
    margin-bottom:6px
}
.af-select-wrap select {
    width:100%;
    background:#12243a;
    color:#eff6ff;
    border:1px solid #357fc0;
    border-radius:8px;
    padding:10px 12px;
    font-size:13px;
    outline:none
}
.af-selected {
    display:flex;
    align-items:center;
    gap:10px;
    padding-bottom:3px
}
.af-drone-symbol {
    font-size:24px;
    color:#57adff
}
.af-selected strong {
    display:block;
    font-size:13px
}
.af-selected small {
    display:block;
    color:#8499b4;
    font-size:9px;
    margin-top:2px
}
.af-pill {
    margin-left:8px;
    font-size:9px;
    letter-spacing:.6px;
    padding:5px 8px;
    border-radius:20px;
    display:flex;
    align-items:center;
    gap:6px
}
.af-pill i {
    width:6px;
    height:6px;
    border-radius:50%;
    background:currentColor
}
.pill-green {
    color:#29dc92;
    background:#10372e
}
.pill-muted {
    color:#a2afc1;
    background:#29384a
}
.af-toolbar-note {
    margin-left:auto;
    color:#7e94ae;
    font-size:10px;
    padding-bottom:8px;
    display:flex;
    align-items:center;
    gap:7px
}
.af-summary {
    display:flex;
    align-items:center;
    background:#101e30;
    border:1px solid #263b55;
    border-radius:11px;
    padding:13px 16px;
    margin-bottom:14px;
    gap:0
}
.af-summary-drone {
    display:flex;
    align-items:center;
    gap:12px;
    min-width:220px;
    flex:1
}
.af-big-drone {
    font-size:31px;
    color:#d7e8fb
}
.af-summary-drone strong {
    font-size:16px;
    margin-right:9px
}
.af-summary-drone small {
    display:block;
    color:#8fa3bc;
    font-size:9px;
    margin-top:4px
}
.af-state {
    font-size:9px;
    padding:4px 7px;
    border-radius:5px;
    font-weight:800
}
.state-flying {
    background:#145b3e;
    color:#4ef0a3
}
.state-other {
    background:#35455b;
    color:#d3dfed
}
.af-summary-stat {
    display:flex;
    align-items:center;
    gap:9px;
    padding:0 17px;
    border-left:1px solid #263b55;
    min-width:105px
}
.af-summary-stat>span {
    font-size:21px;
    color:#8bbfff
}
.af-summary-stat strong {
    display:block;
    font-size:14px
}
.af-summary-stat small {
    display:block;
    font-size:9px;
    color:#8fa3bc;
    margin-top:2px
}
.af-grid {
    display:grid;
    grid-template-columns:1.35fr 1fr 1fr;
    gap:13px
}
.af-card {
    background:linear-gradient(145deg,#111f31,#0d1929);
    border:1px solid #263b55;
    border-radius:11px;
    overflow:hidden;
    min-width:0
}
.af-card-head {
    height:43px;
    display:flex;
    align-items:center;
    justify-content:space-between;
    padding:0 13px;
    border-bottom:1px solid #263b55;
    background:#132338
}
.af-card-head>div {
    display:flex;
    align-items:center;
    gap:9px
}
.af-card-head strong {
    font-size:12px;
    font-weight:700
}
.af-card-icon {
    font-size:17px;
    color:#80baff
}
.af-card-tag {
    font-size:8px;
    letter-spacing:1px;
    color:#7891ad
}
.af-map-card {
    grid-row:span 2
}
.af-map {
    height:clamp(260px,38vh,520px);
    min-height:260px;
    position:relative;
    overflow:hidden;
    background:#142235;
}
.af-leaflet-map {
    position:absolute;
    inset:0;
    width:100%;
    height:100%;
    z-index:1;
    background:#142235;
}
.af-map-coord {
    z-index:500;
    pointer-events:none;
}
.af-map-no-fix {
    position:absolute;
    z-index:500;
    left:50%;
    top:50%;
    transform:translate(-50%,-50%);
    padding:9px 13px;
    border:1px solid #8ca6c455;
    border-radius:7px;
    background:#081522dd;
    color:#e8f0fb;
    font-size:12px;
    text-align:center;
    pointer-events:none;
}
.af-leaflet-tooltip {
    background:#102238;
    border:1px solid #6686a8;
    color:#edf5ff;
