/* =========================================================
   AEROFLEET MONITOR — RESPONSIVE LAYOUT
   ========================================================= */
/* The dashboard wrapper grows with its content.
   The host page only needs to scroll when content really overflows. */
.af-shell {
    display: flex;
    width: 100%;
    height: auto;
    min-height: 0;
    max-height: none;
    overflow: hidden;
    align-items: stretch;
}
.af-main {
    height: auto;
    min-height: 0;
    overflow: visible;
}
.af-monitor-view {
    display: flex;
    flex: 0 0 auto;
    flex-direction: column;
    min-height: 0;
    overflow: visible;
}
/* Three equal columns:
   - Map: left column, spanning two rows.
   - GPS and gyroscope: middle column.
   - Acceleration, incidents and camera: right column. */
.af-monitor-view .af-grid {
    display: grid;
    flex: 0 0 auto;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-template-rows: repeat(3, 165px);
    grid-template-areas:
    "map gps acceleration"
    "map gyroscope incidents"
    ". . camera";
    gap: 13px;
    min-height: 0;
    align-items: stretch;
}
.af-monitor-view .af-grid > .af-card {
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    align-self: stretch;
}
/* Explicit placement keeps the cards in the same order at every refresh. */
.af-monitor-view .af-map-card {
    grid-area: map;
    display: flex;
    flex-direction: column;
}
.af-monitor-view .af-grid > .af-card:nth-child(2) {
    grid-area: gps;
}
.af-monitor-view .af-grid > .af-card:nth-child(3) {
    grid-area: acceleration;
}
.af-monitor-view .af-grid > .af-card:nth-child(4) {
    grid-area: gyroscope;
}
.af-monitor-view .af-grid > .af-card:nth-child(5) {
    grid-area: incidents;
}
.af-monitor-view .af-grid > .af-card:nth-child(6) {
    grid-area: camera;
}
/* The map fills the full height of its double-sized card. */
.af-monitor-view .af-map {
    flex: 1 1 auto;
    height: auto;
    min-height: 0;
}
.af-monitor-view .af-map-footer {
    flex: 0 0 auto;
}
/* Consistent card headers and readable telemetry. */
.af-monitor-view .af-card-head {
    flex: 0 0 42px;
    height: 42px;
    min-height: 42px;
    padding: 0 14px;
}
.af-monitor-view .af-card-head strong {
    font-size: 14px;
}
