    font-size: 13px;
}
.af-monitor-view .af-data-list .af-small-value {
    font-size: 10px;
}
.af-monitor-view .af-axis-list {
    padding: 3px 14px 6px;
}
.af-monitor-view .af-axis-list > div {
    min-height: 30px;
    padding: 5px 0;
}
.af-monitor-view .af-axis-list b {
    font-size: 12px;
}
.af-monitor-view .af-axis-list strong {
    font-size: 15px;
}
.af-monitor-view .af-spark {
