/* Medium screens: keep the map wide and arrange the other cards in two columns. */
@media (max-width: 1100px) {
    .af-shell {
        min-height: 0;
    }
    .af-monitor-view .af-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
