/* =========================================================
   CAMERA PREVIEW
   Square preview with the complete image visible.
   ========================================================= */

.af-monitor-view .af-preview-card {
    display: flex;
    flex-direction: column;
    min-width: 0;
    min-height: 0;
    height: auto;
}

.af-monitor-view .af-preview {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: auto;
    min-width: 0;
    min-height: 0;
    aspect-ratio: 1 / 1;
    position: relative;
    box-sizing: border-box;
    overflow: hidden;
    padding: 0;
    background: #0a1523;
}

.af-monitor-view .af-preview > img {
    display: block;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    object-fit: contain;
    object-position: center;
}

.af-monitor-view .af-preview-empty {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    min-height: 0;
    box-sizing: border-box;
    padding: 18px;
    margin: 0;
    gap: 8px;
    text-align: center;
}

.af-monitor-view .af-preview-empty > span,
.af-monitor-view .af-preview-empty strong,
.af-monitor-view .af-preview-empty small {
    display: block;
    width: 100%;
    margin: 0;
    text-align: center;
}

.af-monitor-view .af-preview-empty > span {
    font-size: 30px;
    line-height: 1.2;
}

.af-monitor-view .af-preview-empty strong {
    font-size: 15px;
    line-height: 1.4;
}

.af-monitor-view .af-preview-empty small {
    font-size: 11px;
    line-height: 1.4;
}

/* Keep a useful square preview on narrow screens. */
@media (max-width: 760px) {
    .af-monitor-view .af-preview {
        min-height: 0;
        aspect-ratio: 1 / 1;
    }
}


